"use client"
function EventForm({ mode, defaultValues }: { mode: 'create'|'edit'; defaultValues?: Partial<EventFormValues> }) {
  const form = useForm<EventFormValues>({ resolver: zodResolver(eventFormSchema), defaultValues: { title:'', location:'', eventDate:'', description:'', coverImageUrl:'', ...defaultValues } })
  function onSubmit(values: EventFormValues) {
    toast.success(mode === 'create' ? '이벤트가 생성되었습니다' : '이벤트가 수정되었습니다')
  }
  return <Form {...form}><form onSubmit={form.handleSubmit(onSubmit)}>
    <FormField name="title" .../> // Input
    <FormField name="location" .../> // Input
    <FormField name="eventDate" .../> // Input type="datetime-local"
    <FormField name="description" .../> // Textarea, optional
    <FormField name="coverImageUrl" .../> // Input, optional, placeholder로 '추후 업로드 기능 연동 예정' 안내
    <Button type="submit">{mode==='create' ? '이벤트 만들기' : '저장'}</Button>
  </form></Form>
}

