// app/(main)/events/new/page.tsx
export default function NewEventPage() { return <div className="p-4"><h1>이벤트 만들기</h1><EventForm mode="create" /></div> }

// app/(main)/events/[id]/edit/page.tsx
export default async function EditEventPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const event = getDummyEventById(id)
  if (!event || event.createdBy !== 'profile-1') notFound()
  const defaultValues = { title: event.title, location: event.location, eventDate: toDatetimeLocal(event.eventDate), description: event.description ?? '', coverImageUrl: event.coverImageUrl ?? '' }
  return <div className="p-4"><h1>이벤트 수정</h1><EventForm mode="edit" defaultValues={defaultValues} /></div>
}

