"use client"
const FILTERS = [{ value: 'all', label: '전체' }, { value: 'upcoming', label: '예정' }, { value: 'ongoing', label: '진행중' }, { value: 'ended', label: '종료' }] as const
function EventsPage() {
  const [filter, setFilter] = useState<'all'|EventStatus>('all')
  const events = getDummyEventCardSummaries()
  const filtered = filter === 'all' ? events : events.filter(e => e.status === filter)
  return <div className="p-4">
    <div className="flex gap-2">{FILTERS.map(f => <button onClick={() => setFilter(f.value)} className={cn(..., filter===f.value && 'bg-primary text-primary-foreground')}>{f.label}</button>)}</div>
    {filtered.length === 0 ? <EmptyState .../> : <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">{filtered.map(e => <Link key={e.id} href={`/events/${e.id}`}><EventCard event={e} /></Link>)}</div>}
  </div>
}

