// components/event-share-actions.tsx
"use client"
function EventShareActions({ inviteCode }: { inviteCode: string }) {
  const copyLink = async () => { await navigator.clipboard.writeText(`${window.location.origin}/join/${inviteCode}`); toast.success('초대 링크가 복사되었습니다') }
  const shareKakao = () => toast.info('카카오톡 공유는 추후 지원 예정입니다')
  return <div className="flex gap-2"><Button onClick={copyLink}>링크 복사</Button><Button variant="outline" onClick={shareKakao}>카카오톡 공유</Button></div>
}

// app/(main)/events/[id]/page.tsx
export default async function EventDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const event = getDummyEventWithParticipants(id)
  if (!event) notFound()
  const isHost = event.createdBy === 'profile-1'
  return <div>...event info... {isHost && <><Link href={`/events/${id}/edit`}>수정</Link><DeleteEventDialog /><EventShareActions inviteCode={event.inviteCode} /></>}
    <div className="space-y-2">{event.participants.map(p => <ParticipantCard key={p.id} participant={p} />)}</div>
  </div>
}

